package ru.oopssre.gremlinamp;
public class Regression {
 static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Check "+checks);}
 public static void main(String[] args){PlaybackIdentity identity=new PlaybackIdentity();identity.begin(1,"DK theme","Donkey Kong");check(identity.artwork(1,"dk.png"));identity.begin(2,"Contra theme","Contra");check(identity.snapshot().art.isEmpty());check(!identity.artwork(1,"dk-late.png"));check(identity.snapshot().game.equals("Contra"));check(identity.artwork(2,"contra.png"));check(identity.snapshot().title.equals("Contra theme"));identity.begin(3,"Next","Another game");check(identity.snapshot().art.isEmpty());check(identity.artwork(3,""));check(identity.snapshot().art.isEmpty());check(PlaybackRules.total(14000,5000)==19000);check(PlaybackRules.position(20000,19000,true)==19000);check(PlaybackRules.position(20000,0,false)==20000);check(PlaybackRules.include(-1,10000,"show"));check(!PlaybackRules.include(-1,10000,"hide"));check(PlaybackRules.include(-1,10000,"only"));check(!PlaybackRules.include(700,10000,"show"));check(PlaybackRules.include(10000,10000,"show"));check(!PlaybackRules.include(20000,0,"only"));System.out.println(checks+" regression checks passed: identity, stale covers, missing covers, duration/fade, unknown-duration filters");}
}
